const c = $input.first().json;

const userPrompt = `Rédige un mail de prospection B2B pour un partenariat / dotation avec un BDE étudiant.

Prospect : ${c.nom}
Entreprise : ${c.entreprise}
Produit / angle d'intérêt : ${c.produit_interesse}

Ton : pro, direct, chaleureux mais concis.
Format : HTML propre (balises p, strong, br), 150 à 200 mots.
Objectif : décrocher un échange court pour parler partenariat / dotation.

Termine TOUJOURS le mail par exactement cette signature, sans rien ajouter après et sans la modifier :
<p>Cordialement,</p>
<p>L'équipe Partenariats - Liste BDE ESSEC</p>
N'utilise JAMAIS de placeholder comme 'Votre prénom et nom' ou '[Nom]'.

Réponds UNIQUEMENT avec le HTML du mail, sans balise html ni body, sans commentaire.`;

return [{
  json: {
    ...c,
    groq_body: {
      model: 'openai/gpt-oss-120b',
      reasoning_effort: 'low',
      messages: [
        {
          role: 'system',
          content: 'Tu es expert copywriting B2B, tu écris des mails de prospection pro en HTML propre'
        },
        {
          role: 'user',
          content: userPrompt
        }
      ],
      temperature: 0.7,
      max_tokens: 2000
    }
  }
}];

const resp = $input.first().json;
const contact = $('S0 - Entrée Contact').first().json;

if (resp && resp.error) {
  throw new Error('Erreur Groq : ' + JSON.stringify(resp.error));
}
if (!resp || !resp.choices || !resp.choices[0] || !resp.choices[0].message) {
  throw new Error('Réponse Groq invalide : ' + JSON.stringify(resp).slice(0, 500));
}

// Nettoie d'éventuelles balises ```html renvoyées par le modèle
let mail_html = (resp.choices[0].message.content || '').trim()
  .replace(/^```(?:html)?\s*/i, '')
  .replace(/```\s*$/, '')
  .trim();

return [{
  json: {
    id: contact.id,
    email: contact.email,
    nom: contact.nom,
    entreprise: contact.entreprise,
    produit_interesse: contact.produit_interesse,
    mail_genere: mail_html,
    mail_sujet: `${contact.nom}, proposition de partenariat`
  }
}];
